import threading
import time
from collections import defaultdict, deque
from typing import Optional


class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float) -> None:
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._lock = threading.Lock()
        self._windows: dict[str, deque] = defaultdict(deque)

    def _cleanup(self, key: str, current_time: float) -> deque:
        window = self._windows[key]
        boundary = current_time - self.window_seconds
        while window and window[0] <= boundary:
            window.popleft()
        return window

    def allow_request(
        self, key: str, timestamp: Optional[float] = None
    ) -> tuple[bool, float]:
        now = time.time() if timestamp is None else float(timestamp)

        with self._lock:
            if self.max_requests <= 0:
                return False, float("inf")

            window = self._cleanup(key, now)

            if len(window) < self.max_requests:
                window.append(now)
                return True, 0.0
            else:
                oldest = window[0]
                retry_after = max(0.0, (oldest + self.window_seconds) - now)
                return False, retry_after

    def get_remaining(
        self, key: str, timestamp: Optional[float] = None
    ) -> int:
        now = time.time() if timestamp is None else float(timestamp)

        with self._lock:
            if self.max_requests <= 0:
                return 0

            window = self._cleanup(key, now)
            return max(0, self.max_requests - len(window))
