from typing import Any


class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        """
        Initializes cluster state with given unique node IDs.
        Quorum threshold is floor(N / 2) + 1.
        """
        self.node_ids = list(node_ids)
        self.quorum_threshold = len(self.node_ids) // 2 + 1
        self.current_version = 0

        # Committed state per node: node_id -> {key: (version, value)}
        self.node_store: dict[str, dict[str, tuple[int, Any]]] = {
            node_id: {} for node_id in self.node_ids
        }

        # Partition mapping: node_id -> set of reachable node_ids
        all_nodes = set(self.node_ids)
        self.node_partitions: dict[str, set[str]] = {
            node_id: all_nodes for node_id in self.node_ids
        }

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """
        Divides cluster into isolated network partitions where nodes in group_a
        can only talk to group_a, and group_b only to group_b.
        """
        set_a = set(group_a)
        set_b = set(group_b)
        self.node_partitions = {}

        for node in set_a:
            self.node_partitions[node] = set_a
        for node in set_b:
            self.node_partitions[node] = set_b

        for node in self.node_ids:
            if node not in self.node_partitions:
                self.node_partitions[node] = {node}

    def heal_partition(self) -> None:
        """
        Restores full connectivity so all nodes can communicate,
        synchronizing committed state across all nodes.
        """
        all_nodes = set(self.node_ids)
        self.node_partitions = {node_id: all_nodes for node_id in self.node_ids}

        # Determine the latest committed value for each key across all nodes
        latest_state: dict[str, tuple[int, Any]] = {}
        for node_id in self.node_ids:
            for key, entry in self.node_store[node_id].items():
                if key not in latest_state or entry[0] > latest_state[key][0]:
                    latest_state[key] = entry

        # Synchronize committed state to all nodes
        for node_id in self.node_ids:
            self.node_store[node_id] = latest_state.copy()

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """
        Proposes a write from from_node.
        If from_node belongs to a partition having a STRICT MAJORITY
        (active partition size >= quorum threshold), the write commits,
        updates state in all nodes within that partition, and returns True.
        Otherwise, returns False.
        """
        partition = self.node_partitions.get(from_node)
        if not partition or len(partition) < self.quorum_threshold:
            return False

        self.current_version += 1
        entry = (self.current_version, value)
        for node_id in partition:
            if node_id in self.node_store:
                self.node_store[node_id][key] = entry

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        """
        Returns the committed value for key on from_node (or None if not set).
        """
        if from_node not in self.node_store:
            return None

        entry = self.node_store[from_node].get(key)
        return entry[1] if entry is not None else None
