from __future__ import annotations


class RetryableError(Exception):
    pass


class FatalError(Exception):
    pass


class CrashError(Exception):
    pass


class SagaOrchestrator:

    def __init__(
        self,
        executor,
        compensator,
        max_retries: int = 2,
        journal: dict | None = None,
    ):
        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        if journal is None:
            journal = {}
        self.journal = journal

    def _validate(self, saga_id: str, steps: list[str]) -> None:
        if not isinstance(saga_id, str):
            raise ValueError("saga_id must be a string")
        if not isinstance(steps, list):
            raise ValueError("steps must be a list of strings")
        for step in steps:
            if not isinstance(step, str) or len(step) == 0:
                raise ValueError("Steps must be non-empty strings")
        if len(steps) != len(set(steps)):
            raise ValueError("Steps must be unique")

        if saga_id in self.journal:
            existing = self.journal[saga_id]
            existing_steps = existing.get("steps")
            if existing_steps is None:
                existing_steps = existing.get("step_plan")
            if existing_steps is not None and existing_steps != steps:
                raise ValueError(
                    f"Changed step plan for existing saga '{saga_id}' is rejected"
                )

    def _run_saga(self, saga_id: str, steps: list[str]) -> str:
        self._validate(saga_id, steps)

        if saga_id not in self.journal:
            completed: list[str] = []
            compensated: list[str] = []
            self.journal[saga_id] = {
                "steps": list(steps),
                "status": "executing",
                "completed": completed,
                "completed_steps": completed,
                "compensated": compensated,
                "compensated_steps": compensated,
            }

        entry = self.journal[saga_id]
        if "steps" not in entry:
            entry["steps"] = list(steps)

        completed = entry.get("completed")
        if completed is None:
            completed = entry.get("completed_steps")
        if completed is None:
            completed = []
            entry["completed"] = completed
            entry["completed_steps"] = completed

        compensated = entry.get("compensated")
        if compensated is None:
            compensated = entry.get("compensated_steps")
        if compensated is None:
            compensated = []
            entry["compensated"] = compensated
            entry["compensated_steps"] = compensated

        status = entry.get("status")
        if status == "completed":
            return "completed"
        if status == "compensated":
            return "compensated"

        if status == "compensating" or (
            bool(compensated) and status != "compensated"
        ):
            return self._compensate(entry)

        for step in steps:
            if step in completed:
                continue

            attempts = 0
            while True:
                try:
                    self.executor(step)
                    completed.append(step)
                    break
                except CrashError:
                    raise
                except RetryableError:
                    if attempts < self.max_retries:
                        attempts += 1
                        continue
                    return self._compensate(entry)
                except FatalError:
                    return self._compensate(entry)
                except Exception:
                    return self._compensate(entry)

        entry["status"] = "completed"
        return "completed"

    def _compensate(self, entry: dict) -> str:
        entry["status"] = "compensating"
        completed = entry.get("completed", [])
        compensated = entry.get("compensated", [])

        for step in reversed(completed):
            if step in compensated:
                continue
            try:
                self.compensator(step)
            except CrashError:
                raise
            compensated.append(step)

        entry["status"] = "compensated"
        return "compensated"

    def run(self, saga_id: str, steps: list[str]) -> str:
        return self._run_saga(saga_id, steps)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        return self._run_saga(saga_id, steps)
