import threading
import time
from collections import OrderedDict
from typing import Any, Optional


class _CacheEntry:
    __slots__ = ("value", "expires_at")

    def __init__(self, value: Any, expires_at: float) -> None:
        self.value = value
        self.expires_at = expires_at


class TimeBoundedLRUCache:
    """A thread-safe LRU cache with per-item time-to-live (TTL) expiration."""

    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0) -> None:
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        if default_ttl_seconds <= 0:
            raise ValueError("Default TTL must be greater than 0")

        self.capacity: int = capacity
        self.default_ttl_seconds: float = default_ttl_seconds
        self._lock: threading.RLock = threading.RLock()
        self._cache: OrderedDict[str, _CacheEntry] = OrderedDict()

    def _is_expired(self, entry: _CacheEntry, current_time: float) -> bool:
        return current_time >= entry.expires_at

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        """Inserts or updates key.

        If capacity is reached, evict the least recently used non-expired item
        (or oldest expired item).
        """
        with self._lock:
            now = time.monotonic()
            ttl_seconds = self.default_ttl_seconds if ttl is None else ttl
            if ttl_seconds <= 0:
                raise ValueError("TTL must be greater than 0")

            expires_at = now + ttl_seconds

            if key in self._cache:
                self._cache[key] = _CacheEntry(value, expires_at)
                self._cache.move_to_end(key)
                return

            if len(self._cache) >= self.capacity:
                # Prioritize evicting an expired item first
                expired_key = None
                for k, entry in self._cache.items():
                    if self._is_expired(entry, now):
                        expired_key = k
                        break

                if expired_key is not None:
                    del self._cache[expired_key]
                else:
                    # Evict the least recently used item
                    self._cache.popitem(last=False)

            self._cache[key] = _CacheEntry(value, expires_at)

    def get(self, key: str) -> Optional[Any]:
        """Returns value if present and not expired, else None.

        Accessing updates LRU recency.
        """
        with self._lock:
            if key not in self._cache:
                return None

            entry = self._cache[key]
            now = time.monotonic()

            if self._is_expired(entry, now):
                del self._cache[key]
                return None

            self._cache.move_to_end(key)
            return entry.value

    def delete(self, key: str) -> bool:
        """Deletes key, returns True if existed and deleted, else False."""
        with self._lock:
            if key in self._cache:
                del self._cache[key]
                return True
            return False

    def cleanup_expired(self) -> int:
        """Removes all expired keys and returns count of removed items."""
        with self._lock:
            now = time.monotonic()
            expired_keys = [
                k for k, entry in self._cache.items() if self._is_expired(entry, now)
            ]
            for k in expired_keys:
                del self._cache[k]
            return len(expired_keys)

    def size(self) -> int:
        """Returns number of currently valid (non-expired) items."""
        with self._lock:
            now = time.monotonic()
            return sum(
                1 for entry in self._cache.values() if not self._is_expired(entry, now)
            )
