class QuorumCluster:
    def __init__(self, node_ids: List[str]) -> None:
        """
        Initializes cluster state with given unique node IDs.
        Total node count N = len(node_ids).
        Quorum threshold is floor(N / 2) + 1.
        """
        self.node_ids: List[str] = list(node_ids)
        self.quorum_threshold: int = len(self.node_ids) // 2 + 1
        self.partitions: List[Set[str]] = [set(self.node_ids)]
        # Map each node to its committed key-value state: {node_id: {key: (value, sequence_number)}}
        self.node_states: Dict[str, Dict[str, Tuple[Any, int]]] = {
            node_id: {} for node_id in self.node_ids
        }
        self._seq: int = 0

    def partition(self, group_a: List[str], group_b: List[str]) -> None:
        """
        Divides cluster into isolated network partitions where nodes in group_a
        can only talk to group_a, and group_b only to group_b.
        """
        set_a = set(group_a)
        set_b = set(group_b)
        remaining = set(self.node_ids) - set_a - set_b

        self.partitions = [set_a, set_b]
        for node in remaining:
            self.partitions.append({node})

    def heal_partition(self) -> None:
        """
        Restores full connectivity so all nodes can communicate,
        synchronizing committed state across all nodes.
        """
        # Restore full connectivity
        self.partitions = [set(self.node_ids)]

        # Find the latest committed state for each key across all nodes
        latest_state: Dict[str, Tuple[Any, int]] = {}
        for node_id in self.node_ids:
            for key, entry in self.node_states[node_id].items():
                if key not in latest_state or entry[1] > latest_state[key][1]:
                    latest_state[key] = entry

        # Synchronize committed state to every node in the cluster
        for node_id in self.node_ids:
            self.node_states[node_id] = {
                key: entry for key, entry in latest_state.items()
            }

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """
        Proposes a write from from_node.
        If from_node belongs to a partition having a STRICT MAJORITY (>= quorum threshold),
        the write commits, updates state in all nodes within that partition, and returns True.
        Otherwise, returns False.
        """
        if from_node not in self.node_ids:
            return False

        # Identify the active partition containing from_node
        active_partition: Optional[Set[str]] = None
        for partition in self.partitions:
            if from_node in partition:
                active_partition = partition
                break

        if active_partition is None or len(active_partition) < self.quorum_threshold:
            return False

        # Commit write to all nodes in the majority partition
        self._seq += 1
        for node_id in active_partition:
            self.node_states[node_id][key] = (value, self._seq)

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        """
        Returns the committed value for key on from_node (or None if not set).
        """
        if from_node not in self.node_ids:
            return None

        node_data = self.node_states.get(from_node, {})
        if key in node_data:
            return node_data[key][0]
        return None
