class CircularDependencyError(Exception):
    """Raised when a circular dependency is detected between tasks."""
    pass


class DependencyResolver:
    """Resolves task dependencies into parallel execution stages."""

    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        """
        Resolves dependencies into ordered stages of tasks that can run in parallel.

        :param dependencies: Dictionary mapping task_name -> list of task_names it depends on.
        :return: List of stages, where each stage is a sorted list of task names.
        :raises CircularDependencyError: If any circular dependency exists.
        """
        # Collect all tasks (including those that only appear as dependencies)
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        # Build in-degree map (task -> set of unresolved dependencies)
        # and reverse map (dependency -> set of dependent tasks)
        task_deps = {task: set(dependencies.get(task, [])) for task in all_tasks}
        dependents: dict[str, set[str]] = {task: set() for task in all_tasks}
        for task, deps in task_deps.items():
            for dep in deps:
                dependents[dep].add(task)

        stages = []
        processed_count = 0

        # Stage 0: Tasks with no dependencies
        current_stage = [task for task, deps in task_deps.items() if not deps]

        while current_stage:
            current_stage.sort()
            stages.append(current_stage)
            processed_count += len(current_stage)

            next_stage = []
            for task in current_stage:
                for dependent in dependents[task]:
                    task_deps[dependent].remove(task)
                    if not task_deps[dependent]:
                        next_stage.append(dependent)

            current_stage = next_stage

        if processed_count < len(all_tasks):
            raise CircularDependencyError("Circular dependency detected among tasks.")

        return stages
