import threading


class ResilientConnectionPool:
    """A robust database connection pool wrapper."""

    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0) -> None:
        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.Lock()
        self._pool: list[dict] = [
            {"id": i, "alive": True} for i in range(1, max_connections + 1)
        ]
        self._next_id = max_connections + 1

    def acquire(self) -> dict:
        """Returns an active connection object {"id": int, "alive": bool}.

        Raises RuntimeError("Pool exhausted") if no connections are available.
        """
        with self._lock:
            if not self._pool:
                raise RuntimeError("Pool exhausted")
            return self._pool.pop(0)

    def release(self, conn: dict) -> None:
        """Returns a connection back to the pool."""
        with self._lock:
            if conn is not None:
                self._pool.append(conn)

    def health_check_and_heal(self) -> int:
        """Iterates over pool connections, checks if conn["alive"] is False,

        recreates them with new alive connections, and returns the number of
        healed connections.
        """
        with self._lock:
            healed_count = 0
            for i in range(len(self._pool)):
                if not self._pool[i].get("alive", False):
                    self._pool[i] = {"id": self._next_id, "alive": True}
                    self._next_id += 1
                    healed_count += 1
            return healed_count

    def close_all(self) -> None:
        """Closes and empties the pool."""
        with self._lock:
            for conn in self._pool:
                conn["alive"] = False
            self._pool.clear()
