import fnmatch


def authorize(request: dict, policies: list[dict]) -> bool:
    if not isinstance(request, dict):
        return False

    required_req_keys = {
        "subject_id",
        "tenant_id",
        "resource_tenant_id",
        "roles",
        "action",
        "resource",
        "context",
    }
    if not required_req_keys.issubset(request.keys()):
        return False

    sub_id = request["subject_id"]
    t_id = request["tenant_id"]
    res_t_id = request["resource_tenant_id"]
    roles = request["roles"]
    action = request["action"]
    resource = request["resource"]
    context = request["context"]

    if not isinstance(sub_id, str) or not sub_id:
        return False
    if not isinstance(t_id, str) or not t_id:
        return False
    if not isinstance(res_t_id, str) or not res_t_id:
        return False
    if t_id != res_t_id:
        return False
    if not isinstance(roles, list) or not all(isinstance(r, str) for r in roles):
        return False
    if not isinstance(action, str):
        return False
    if not isinstance(resource, str):
        return False
    if not isinstance(context, dict):
        return False

    if not isinstance(policies, list):
        return False

    required_pol_keys = {"effect", "tenant", "roles", "actions", "resources"}
    for p in policies:
        if not isinstance(p, dict):
            return False
        if not required_pol_keys.issubset(p.keys()):
            return False
        if p["effect"] not in ("allow", "deny"):
            return False
        if not isinstance(p["tenant"], str):
            return False

        p_roles = p["roles"]
        if (
            not isinstance(p_roles, list)
            or len(p_roles) == 0
            or not all(isinstance(r, str) for r in p_roles)
        ):
            return False

        p_actions = p["actions"]
        if (
            not isinstance(p_actions, list)
            or len(p_actions) == 0
            or not all(isinstance(a, str) for a in p_actions)
        ):
            return False

        p_resources = p["resources"]
        if (
            not isinstance(p_resources, list)
            or len(p_resources) == 0
            or not all(isinstance(res, str) for res in p_resources)
        ):
            return False

        if "conditions" in p:
            if not isinstance(p["conditions"], dict):
                return False

    has_allow = False

    for p in policies:
        if p["tenant"] != "*" and p["tenant"] != t_id:
            continue

        p_roles = p["roles"]
        role_matched = (
            ("*" in p_roles)
            or ("*" in roles)
            or any(r == pr for r in roles for pr in p_roles)
        )
        if not role_matched:
            continue

        action_matched = any(
            fnmatch.fnmatchcase(action, pat) for pat in p["actions"]
        )
        if not action_matched:
            continue

        resource_matched = any(
            fnmatch.fnmatchcase(resource, pat) for pat in p["resources"]
        )
        if not resource_matched:
            continue

        conds = p.get("conditions", {})
        conds_matched = True
        for k, cond_val in conds.items():
            if k not in context:
                conds_matched = False
                break
            ctx_val = context[k]

            if isinstance(cond_val, (list, tuple, set)):
                try:
                    m = ctx_val in cond_val
                except TypeError:
                    m = False
                if not m and isinstance(ctx_val, (list, tuple, set)):
                    try:
                        m = any(v in cond_val for v in ctx_val)
                    except TypeError:
                        m = False
                if not m:
                    conds_matched = False
                    break
            else:
                m = ctx_val == cond_val
                if not m and isinstance(ctx_val, (list, tuple, set)):
                    try:
                        m = cond_val in ctx_val
                    except TypeError:
                        m = False
                if not m:
                    conds_matched = False
                    break

        if not conds_matched:
            continue

        if p["effect"] == "deny":
            return False
        elif p["effect"] == "allow":
            has_allow = True

    return has_allow
