        if set(event.keys()) != required_fields:
            raise ValueError(f"Event must contain exactly the required fields: {required_fields}")

        event_id = event['event_id']
        payment_id = event['payment_id']
        sequence = event['sequence']
        event_type = event['type']
        amount = event['amount']

        if event_id is None:
            raise ValueError("event_id cannot be None")
        try:
            hash(event_id)
        except TypeError:
            raise ValueError("event_id must be hashable")

        if payment_id is None:
            raise ValueError("payment_id cannot be None")
        try:
            hash(payment_id)
        except TypeError:
            raise ValueError("payment_id must be hashable")

        if not isinstance(sequence, int) or isinstance(sequence, bool) or sequence <= 0:
            raise ValueError("sequence must be a positive integer")

        valid_types = {'authorized', 'captured', 'refunded', 'reversed'}
        if event_type not in valid_types:
            raise ValueError(f"Invalid event type: {event_type}")

        if not isinstance(amount, str):
            raise ValueError("amount must be a string")

        if not re.match(r'^\d+(\.\d{1,2})?$', amount):
            raise ValueError("amount must be a positive decimal string with at most two fractional digits")

        try:
            dec_amount = Decimal(amount)
        except InvalidOperation:
            raise ValueError("Invalid decimal amount")

        if dec_amount <= Decimal('0'):
            raise ValueError("amount must be positive")

        event_copy = {
            'event_id': event_id,
            'payment_id': payment_id,
            'sequence': sequence,
            'type': event_type,
            'amount': amount,
        }

        # 2. Check event_id reuse / duplicates
        if event_id in self._events_by_id:
            existing_event = self._events_by_id[event_id]
            if existing_event == event_copy:
                return 'duplicate'
            else:
                raise ValueError(f"Event ID '{event_id}' reused with different content")

        # 3. Check sequence reuse for this payment
        if (payment_id, sequence) in self._seq_map:
            raise ValueError(f"Sequence {sequence} for payment '{payment_id}' reused with different content")

        # Determine current expected sequence for payment
        if payment_id in self._payment_states:
            curr_next_seq = self._payment_states[payment_id]['next_sequence']
        else:
            curr_next_seq = 1

        if sequence < curr_next_seq:
            raise ValueError(f"Sequence {sequence} is less than next expected sequence {curr_next_seq}")

        # 4. Handle future events (buffering)
        if sequence > curr_next_seq:
            self._events_by_id[event_id] = event_copy
            self._seq_map[(payment_id, sequence)] = event_id
            if payment_id not in self._buffers:
                self._buffers[payment_id] = {}
            self._buffers[payment_id][sequence] = event_copy
            return 'buffered'

        # 5. Handle current event & drain consecutive buffered events atomically
        events_to_apply = [event_copy]
        check_seq = sequence + 1
        payment_buffer = self._buffers.get(payment_id, {})
        while check_seq in payment_buffer:
            events_to_apply.append(payment_buffer[check_seq])
            check_seq += 1

        # Simulate state transitions on a copy of the state
        if payment_id in self._payment_states:
            sim_state = {
                'authorized': self._payment_states[payment_id]['authorized'],
                'captured': self._payment_states[payment_id]['captured'],
                'refunded': self._payment_states[payment_id]['refunded'],
                'reversed': self._payment_states[payment_id]['reversed'],
                'next_sequence': self._payment_states[payment_id]['next_sequence'],
            }
        else:
            sim_state = {
                'authorized': Decimal('0'),
                'captured': Decimal('0'),
                'refunded': Decimal('0'),
                'reversed': Decimal('0'),
                'next_sequence': 1,
            }

        for item in events_to_apply:
            item_type = item['type']
            item_amt = Decimal(item['amount'])

            if sim_state['next_sequence'] == 1:
                if item_type != 'authorized':
                    raise ValueError(f"Sequence 1 must be 'authorized', got '{item_type}'")

            if item_type == 'authorized':
                sim_state['authorized'] += item_amt
            elif item_type == 'captured':
                available = sim_state['authorized'] - sim_state['captured']
                if item_amt > available:
                    raise ValueError(f"Capture amount {item_amt} exceeds available authorization {available}")
                sim_state['captured'] += item_amt
            elif item_type == 'refunded':
                remaining_settled = sim_state['captured'] - sim_state['refunded'] - sim_state['reversed']
                if item_amt > remaining_settled:
                    raise ValueError(f"Refund amount {item_amt} exceeds remaining settled amount {remaining_settled}")
                sim_state['refunded'] += item_amt
            elif item_type == 'reversed':
                remaining_settled = sim_state['captured'] - sim_state['refunded'] - sim_state['reversed']
                if item_amt > remaining_settled:
                    raise ValueError(f"Reversal amount {item_amt} exceeds remaining settled amount {remaining_settled}")
                sim_state['reversed'] += item_amt

            sim_state['next_sequence'] += 1

        # Commit state updates atomically
        self._payment_states[payment_id] = sim_state

        for item in events_to_apply:
            item_id = item['event_id']
            item_seq = item['sequence']
            self._events_by_id[item_id] = item
            self._seq_map[(payment_id, item_seq)] = item_id
            if payment_id in self._buffers and item_seq in self._buffers[payment_id]:
                del self._buffers[payment_id][item_seq]

        return 'applied'

    def state(self, payment_id: Any) -> Optional[Dict[str, Any]]:
        if payment_id not in self._payment_states:
            return None
        st = self._payment_states[payment_id]
        auth = st['authorized']
        cap = st['captured']
        ref = st['refunded']
        rev = st['reversed']
        avail = auth - cap
        balance = cap - ref - rev
        return {
            'authorized': f"{auth:.2f}",
            'captured': f"{cap:.2f}",
            'refunded': f"{ref:.2f}",
            'reversed': f"{rev:.2f}",
            'available_to_capture': f"{avail:.2f}",
            'merchant_balance': f"{balance:.2f}",
            'next_sequence': st['next_sequence'],
        }

    def snapshot(self) -> Dict[Any, Dict[str, Any]]:
        return {pid: self.state(pid) for pid in sorted(self._payment_states.keys())}
