class RetryableError(Exception):
    pass


class FatalError(Exception):
    pass


class CrashError(Exception):
    pass


class SagaOrchestrator:
    def __init__(
        self,
        executor,
        compensator,
        max_retries: int = 2,
        journal: dict | None = None,
    ):
        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        self.journal = journal if journal is not None else {}

    def _validate(self, saga_id: str, steps: list[str]) -> None:
        if not isinstance(saga_id, str) or not saga_id:
            raise ValueError("saga_id must be a non-empty string")
        if not isinstance(steps, list):
            raise ValueError("steps must be a list")
        if not all(isinstance(s, str) and len(s) > 0 for s in steps):
            raise ValueError("All steps must be non-empty strings")
        if len(steps) != len(set(steps)):
            raise ValueError("Steps must be unique")

        if saga_id in self.journal:
            stored_steps = self.journal[saga_id].get("steps")
            if stored_steps != steps:
                raise ValueError("Step plan does not match existing saga")

    def _orchestrate(self, saga_id: str, steps: list[str]) -> str:
        self._validate(saga_id, steps)

        if saga_id not in self.journal:
            self.journal[saga_id] = {
                "steps": list(steps),
                "completed": [],
                "status": "in_progress",
            }

        record = self.journal[saga_id]
        status = record.get("status", "in_progress")

        if status == "completed":
            return "completed"
        if status == "compensated":
            return "compensated"
        if status == "compensating":
            return self._compensate(saga_id)

        for step in steps:
            if step in record["completed"]:
                continue

            attempts = 0
            max_attempts = 1 + self.max_retries
            step_success = False

            while attempts < max_attempts:
                try:
                    self.executor(step)
                    step_success = True
                    break
                except CrashError:
                    raise
                except RetryableError:
                    attempts += 1
                    if attempts >= max_attempts:
                        break
                except FatalError:
                    break
                except Exception:
                    break

            if step_success:
                record["completed"].append(step)
            else:
                return self._compensate(saga_id)

        record["status"] = "completed"
        return "completed"

    def _compensate(self, saga_id: str) -> str:
        record = self.journal[saga_id]
        record["status"] = "compensating"

        completed_steps = list(reversed(record["completed"]))
        for step in completed_steps:
            attempts = 0
            max_attempts = 1 + self.max_retries

            while attempts < max_attempts:
                try:
                    self.compensator(step)
                    break
                except CrashError:
                    raise
                except RetryableError:
                    attempts += 1
                    if attempts >= max_attempts:
                        break
                except FatalError:
                    break
                except Exception:
                    break

            if step in record["completed"]:
                record["completed"].remove(step)

        record["status"] = "compensated"
        return "compensated"

    def run(self, saga_id: str, steps: list[str]) -> str:
        return self._orchestrate(saga_id, steps)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        return self._orchestrate(saga_id, steps)
