import time
from threading import RLock
from typing import Any, Optional
from collections import OrderedDict


class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        self.capacity = capacity
        self.default_ttl = default_ttl_seconds
        # OrderedDict maintains insertion order. 
        # When an item is accessed/updated, it will be moved to the end.
        # Thus, the first item is always the Least Recently Used (LRU).
        self.cache: OrderedDict[str, tuple[Any, float]] = OrderedDict()
        self.lock = RLock()

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self.lock:
            if self.capacity <= 0:
                return

            ttl_to_use = ttl if ttl is not None else self.default_ttl
            expiry = time.time() + ttl_to_use

            if key in self.cache:
                self.cache.move_to_end(key)
                self.cache[key] = (value, expiry)
            else:
                self.cache[key] = (value, expiry)
                if len(self.cache) > self.capacity:
                    self._evict()

    def _evict(self) -> None:
        now = time.time()
        expired_key = None

        # Iterate from the least recently used to most recently used
        for k, (_, exp) in self.cache.items():
            if now >= exp:
                expired_key = k
                break

        if expired_key is not None:
            # Evict the oldest (in terms of LRU) expired item
            del self.cache[expired_key]
        else:
            # No expired items found, evict the least recently used non-expired item
            self.cache.popitem(last=False)

    def get(self, key: str) -> Optional[Any]:
        with self.lock:
            if key in self.cache:
                value, expiry = self.cache[key]
                if time.time() < expiry:
                    self.cache.move_to_end(key)
                    return value
                else:
                    # Lazy eviction of expired items on access
                    del self.cache[key]
            return None

    def delete(self, key: str) -> bool:
        with self.lock:
            if key in self.cache:
                del self.cache[key]
                return True
            return False

    def cleanup_expired(self) -> int:
        with self.lock:
            now = time.time()
            expired_keys = [k for k, (_, exp) in self.cache.items() if now >= exp]
            for k in expired_keys:
                del self.cache[k]
            return len(expired_keys)

    def size(self) -> int:
        with self.lock:
            now = time.time()
            return sum(1 for _, exp in self.cache.values() if now < exp)
