import time
import threading
from collections import deque, defaultdict
from typing import Optional

class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        if max_requests <= 0:
            raise ValueError("max_requests must be greater than 0")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be greater than 0")

        self.max_requests = max_requests
        self.window_seconds = float(window_seconds)
        self.requests = defaultdict(deque)
        self.lock = threading.Lock()

    def _cleanup_old_requests(self, key: str, current_time: float) -> None:
        """Removes timestamps outside the current window."""
        cutoff_time = current_time - self.window_seconds
        req_deque = self.requests[key]

        while req_deque and req_deque[0] <= cutoff_time:
            req_deque.popleft()

        # Clean up empty deques to prevent memory leaks for inactive keys
        if not req_deque and key in self.requests:
            del self.requests[key]

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            self._cleanup_old_requests(key, timestamp)

            req_deque = self.requests[key]
            if len(req_deque) < self.max_requests:
                req_deque.append(timestamp)
                return True, 0.0
            else:
                retry_after = (req_deque[0] + self.window_seconds) - timestamp
                return False, max(0.0, retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            self._cleanup_old_requests(key, timestamp)
            if key not in self.requests:
                return self.max_requests
            return max(0, self.max_requests - len(self.requests[key]))
