from typing import Any

class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        self.node_ids = node_ids
        self.quorum_threshold = len(node_ids) // 2 + 1
        # state per node: node_id -> {key: (value, version)}
        self.state = {n: {} for n in node_ids}
        # partitions: node_id -> set of node_ids it can communicate with
        self.partitions = {n: set(node_ids) for n in node_ids}
        # A monotonic clock to order successful writes
        self.global_version = 0

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        group_a_set = set(group_a)
        group_b_set = set(group_b)

        for n in group_a:
            if n in self.partitions:
                self.partitions[n] = group_a_set

        for n in group_b:
            if n in self.partitions:
                self.partitions[n] = group_b_set

    def heal_partition(self) -> None:
        # Restore full connectivity
        full_set = set(self.node_ids)
        for n in self.node_ids:
            self.partitions[n] = full_set

        # Find the latest committed state for each key across all nodes
        latest_state = {}
        for n in self.node_ids:
            for k, (v, ver) in self.state[n].items():
                if k not in latest_state or ver > latest_state[k][1]:
                    latest_state[k] = (v, ver)

        # Synchronize this latest state to all nodes
        for n in self.node_ids:
            for k, val_ver in latest_state.items():
                self.state[n][k] = val_ver

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        if from_node not in self.partitions:
            return False

        reachable_nodes = self.partitions[from_node]

        # Write is REJECTED if the partition doesn't have a strict majority
        if len(reachable_nodes) < self.quorum_threshold:
            return False

        # Write commits: increment logical clock and update all reachable nodes
        self.global_version += 1
        for n in reachable_nodes:
            if n in self.state:
                self.state[n][key] = (value, self.global_version)

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        if from_node not in self.state:
            return None

        node_state = self.state[from_node]
        if key in node_state:
            return node_state[key][0]

        return None
