import os
import shutil
import stat
import unicodedata
import zipfile

def safe_extract_zip(
    archive_path: str,
    destination: str,
    max_files: int = 1000,
    max_uncompressed_bytes: int = 10000000,
    max_compression_ratio: float = 100.0
) -> list[str]:
    with zipfile.ZipFile(archive_path, 'r') as zf:
        infolist = zf.infolist()

        file_count = 0
        total_size = 0
        seen_paths = set()
        file_paths = set()
        dir_paths = set()

        valid_entries = []

        # Pass 1: Validate the entire archive
        for info in infolist:
            filename = info.filename

            if '\0' in filename:
                raise ValueError("NUL byte in filename")

            norm_name = unicodedata.normalize('NFC', filename)
            if '\0' in norm_name:
                raise ValueError("NUL byte in normalized filename")

            # Check for absolute paths
            if norm_name.startswith('/') or norm_name.startswith('\\'):
                raise ValueError("Absolute path")
            if len(norm_name) >= 2 and norm_name[1] == ':' and norm_name[0].isalpha():
                raise ValueError("Absolute path with drive letter")

            # Check for Unix symlinks
            if stat.S_ISLNK(info.external_attr >> 16):
                raise ValueError("Unix symlink")

            posix_name = norm_name.replace('\\', '/')
            is_dir = info.is_dir() or posix_name.endswith('/')

            # Resolve components and check for escaping
            parts = posix_name.split('/')
            depth = 0
            canonical_parts = []
            for part in parts:
                if part == '..':
                    depth -= 1
                    if depth < 0:
                        raise ValueError("Escapes through ..")
                    if canonical_parts:
                        canonical_parts.pop()
                elif part != '.' and part != '':
                    depth += 1
                    canonical_parts.append(part)

            if canonical_parts:
                first_part = canonical_parts[0]
                if len(first_part) >= 2 and first_part[1] == ':' and first_part[0].isalpha():
                    raise ValueError("Drive letter after resolving ..")

            canonical_path = '/'.join(canonical_parts)

            if canonical_path == "" and not is_dir:
                raise ValueError("File entry resolves to root directory")

            # Check for name collisions after NFC normalization
            if canonical_path in seen_paths:
                raise ValueError(f"Name collision detected: {canonical_path}")
            seen_paths.add(canonical_path)

            if is_dir:
                if canonical_path != "":
                    dir_paths.add(canonical_path)
            else:
                if canonical_path != "":
                    file_paths.add(canonical_path)

                # File limits validation
                file_count += 1
                if file_count > max_files:
                    raise ValueError("Exceeds max_files limit")

                total_size += info.file_size
                if total_size > max_uncompressed_bytes:
                    raise ValueError("Exceeds cumulative uncompressed-size limit")

                if info.file_size < 0 or info.compress_size < 0:
                    raise ValueError("Negative size in archive entry")

                if info.compress_size == 0:
                    if info.file_size > 0:
                        raise ValueError("Compression ratio exceeded (zero compress_size with data)")
                else:
                    if (info.file_size / info.compress_size) > max_compression_ratio:
                        raise ValueError("Compression ratio exceeded")

            valid_entries.append((info, canonical_path, is_dir))

        # Detect hierarchy collisions (e.g., 'a/b' is a file, but 'a/b/c' expects 'a/b' to be a directory)
        intermediate_dirs = set()
        for p in file_paths | dir_paths:
            if not p:
                continue
            parts = p.split('/')
            for i in range(1, len(parts)):
                parent = '/'.join(parts[:i])
                intermediate_dirs.add(parent)

        intersection = file_paths.intersection(intermediate_dirs)
        if intersection:
            raise ValueError(f"File/directory hierarchy collision: {intersection}")

        # Pass 2: Extract files securely (only reached if Pass 1 succeeds entirely)
        extracted_paths = []
        for info, canonical_path, is_dir in valid_entries:
            if canonical_path == "":
                continue  # Safe to skip the root directory itself

            target_path = os.path.join(destination, os.path.normpath(canonical_path))

            if is_dir:
                os.makedirs(target_path, exist_ok=True)
            else:
                os.makedirs(os.path.dirname(target_path), exist_ok=True)
                with zf.open(info, 'r') as source, open(target_path, 'wb') as target:
                    shutil.copyfileobj(source, target)
                extracted_paths.append(canonical_path)

        return sorted(extracted_paths)
