import fnmatch

def authorize(request: dict, policies: list[dict]) -> bool:
    if not isinstance(request, dict):
        return False

    for key in ('subject_id', 'tenant_id', 'resource_tenant_id', 'action', 'resource'):
        if key not in request or not isinstance(request[key], str) or not request[key]:
            return False

    if 'roles' not in request or not isinstance(request['roles'], list) or not request['roles'] or not all(isinstance(r, str) for r in request['roles']):
        return False

    if 'context' not in request or not isinstance(request['context'], dict):
        return False

    if request['tenant_id'] != request['resource_tenant_id']:
        return False

    if not isinstance(policies, list):
        return False

    for pol in policies:
        if not isinstance(pol, dict):
            return False
        if pol.get('effect') not in ('allow', 'deny'):
            return False
        if 'tenant' not in pol:
            return False
        for key in ('roles', 'actions', 'resources'):
            if key not in pol or not isinstance(pol[key], list) or not pol[key]:
                return False
        if 'conditions' in pol and not isinstance(pol['conditions'], dict):
            return False

    allow_match = False

    for pol in policies:
        if pol['tenant'] != request['tenant_id'] and pol['tenant'] != '*':
            continue

        if '*' in pol['roles']:
            role_match = True
        else:
            role_match = any(r in pol['roles'] for r in request['roles'])

        if not role_match:
            continue

        if not any(fnmatch.fnmatchcase(request['action'], p) for p in pol['actions']):
            continue

        if not any(fnmatch.fnmatchcase(request['resource'], p) for p in pol['resources']):
            continue

        cond_match = True
        if 'conditions' in pol:
            for k, v in pol['conditions'].items():
                if k not in request['context']:
                    cond_match = False
                    break

                req_v = request['context'][k]
                if isinstance(v, list):
                    if req_v not in v:
                        cond_match = False
                        break
                else:
                    if req_v != v:
                        cond_match = False
                        break

        if not cond_match:
            continue

        if pol['effect'] == 'deny':
            return False
        elif pol['effect'] == 'allow':
            allow_match = True

    return allow_match
