            return False
        if set(event.keys()) != {'event_id', 'payment_id', 'sequence', 'type', 'amount'}:
            return False
        if type(event['sequence']) is not int or event['sequence'] <= 0:
            return False
        if type(event['type']) is not str or event['type'] not in {'authorized', 'captured', 'refunded', 'reversed'}:
            return False
        if type(event['amount']) is not str:
            return False
        if not self.amount_pattern.match(event['amount']):
            return False
        try:
            d = decimal.Decimal(event['amount'])
            if d <= decimal.Decimal('0'):
                return False
            if d.as_tuple().exponent < -2:
                return False
        except decimal.InvalidOperation:
            return False

        try:
            hash(event['event_id'])
            hash(event['payment_id'])
        except TypeError:
            return False

        return True

    def _apply_event_to_state(self, pmt: dict, event: dict):
        seq = event['sequence']
        if seq != pmt['next_sequence']:
            raise ValueError("Sequence mismatch")

        amount = decimal.Decimal(event['amount'])
        ev_type = event['type']

        if seq == 1:
            if ev_type != 'authorized':
                raise ValueError("Sequence 1 must authorize")
            pmt['authorized'] += amount
        else:
            if ev_type == 'authorized':
                raise ValueError("Cannot authorize after sequence 1")
            elif ev_type == 'captured':
                if pmt['captured'] + amount > pmt['authorized']:
                    raise ValueError("Captures cannot exceed authorization")
                pmt['captured'] += amount
            elif ev_type in ('refunded', 'reversed'):
                available = pmt['captured'] - pmt['refunded'] - pmt['reversed']
                if amount > available:
                    raise ValueError(f"{ev_type} cannot exceed remaining settled")
                if ev_type == 'refunded':
                    pmt['refunded'] += amount
                else:
                    pmt['reversed'] += amount

        pmt['next_sequence'] += 1

    def apply(self, event: dict) -> str:
        if not self._is_valid_event(event):
            raise ValueError("Invalid event")

        ev_id = event['event_id']
        if ev_id in self.seen_events:
            if self.seen_events[ev_id] == event:
                return "duplicate"
            else:
                raise ValueError("Event ID reused with different content")

        pmt_id = event['payment_id']
        seq = event['sequence']

        pmt = self.payments.get(pmt_id)
        if pmt is None:
            pmt = {
                'authorized': decimal.Decimal('0'),
                'captured': decimal.Decimal('0'),
                'refunded': decimal.Decimal('0'),
                'reversed': decimal.Decimal('0'),
                'next_sequence': 1,
                'buffer': {}
            }

        if seq < pmt['next_sequence']:
            raise ValueError("Sequence reused with different content")

        if seq > pmt['next_sequence']:
            if seq in pmt['buffer']:
                raise ValueError("Sequence reused with different content")
            self.seen_events[ev_id] = event
            pmt['buffer'][seq] = event
            self.payments[pmt_id] = pmt
            return "buffered"

        # Atomically test current event and close gap if necessary
        pmt_copy = {
            'authorized': pmt['authorized'],
            'captured': pmt['captured'],
            'refunded': pmt['refunded'],
            'reversed': pmt['reversed'],
            'next_sequence': pmt['next_sequence'],
            'buffer': dict(pmt['buffer'])
        }

        events_to_apply = [event]
        curr_seq = seq
        while (curr_seq + 1) in pmt_copy['buffer']:
            curr_seq += 1
            events_to_apply.append(pmt_copy['buffer'][curr_seq])

        for ev in events_to_apply:
            self._apply_event_to_state(pmt_copy, ev)

        for ev in events_to_apply[1:]:
            del pmt_copy['buffer'][ev['sequence']]

        self.payments[pmt_id] = pmt_copy
        self.seen_events[ev_id] = event
        return "applied"

    def state(self, payment_id) -> dict | None:
        pmt = self.payments.get(payment_id)
        if not pmt:
            return None
        return {
            'authorized': f"{pmt['authorized']:.2f}",
            'captured': f"{pmt['captured']:.2f}",
            'refunded': f"{pmt['refunded']:.2f}",
            'reversed': f"{pmt['reversed']:.2f}",
            'available_to_capture': f"{(pmt['authorized'] - pmt['captured']):.2f}",
            'merchant_balance': f"{(pmt['captured'] - pmt['refunded'] - pmt['reversed']):.2f}",
            'next_sequence': pmt['next_sequence']
        }

    def snapshot(self) -> dict:
        return {pid: self.state(pid) for pid in sorted(self.payments.keys())}
