class RetryableError(Exception):
    """Raised to indicate a step should be retried."""
    pass


class FatalError(Exception):
    """Raised to indicate a step failed and should trigger compensation."""
    pass


class CrashError(Exception):
    """Raised to indicate an immediate halt without starting extra work."""
    pass


class SagaOrchestrator:
    def __init__(self, executor, compensator, max_retries: int = 2, journal: dict | None = None):
        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        self.journal = journal if journal is not None else {}

    def run(self, saga_id: str, steps: list[str]) -> str:
        return self._execute(saga_id, steps)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        return self._execute(saga_id, steps)

    def _validate_steps(self, steps: list[str]) -> None:
        if not isinstance(steps, list):
            raise TypeError("Steps must be a list of strings.")
        seen = set()
        for step in steps:
            if not isinstance(step, str) or not step:
                raise ValueError("Steps must be unique non-empty strings.")
            if step in seen:
                raise ValueError("Steps must be unique non-empty strings.")
            seen.add(step)

    def _execute(self, saga_id: str, steps: list[str]) -> str:
        self._validate_steps(steps)

        if saga_id in self.journal:
            if self.journal[saga_id]['steps'] != steps:
                raise ValueError("Changed step plan for an existing saga.")
        else:
            self.journal[saga_id] = {
                'steps': list(steps),
                'completed_steps': [],
                'compensating': False,
                'compensated_steps': []
            }

        state = self.journal[saga_id]

        if not state['compensating']:
            for step in steps:
                if step in state['completed_steps']:
                    continue
                try:
                    self._invoke_callback(self.executor, step)
                    state['completed_steps'].append(step)
                except FatalError:
                    state['compensating'] = True
                    break

        if state['compensating']:
            for step in reversed(state['completed_steps']):
                if step in state['compensated_steps']:
                    continue
                self._invoke_callback(self.compensator, step)
                state['compensated_steps'].append(step)
            return 'compensated'

        return 'completed'

    def _invoke_callback(self, callback, step: str) -> None:
        attempts = 0
        while True:
            try:
                callback(step)
                return
            except RetryableError:
                if attempts >= self.max_retries:
                    raise FatalError("Exhausted max retries for RetryableError.")
                attempts += 1
            except (FatalError, CrashError):
                raise
            except Exception as e:
                raise FatalError("Unhandled exception treated as fatal.") from e
